/* Persistent actors: movement interpolates without rebuilding sprites. */
window.CenizasBattleVisuals=(()=>{
const $=id=>document.getElementById(id),previous=new Map();let roomKey='',boardRef=null;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const sprites={
 anchor:{file:'scenes/umbral.png',scale:1.25,frames:Array(4).fill([646,20,891,335,770,332])},
 pylon:{file:'scenes/umbral.png',scale:1.25,frames:Array(4).fill([204,86,362,407,282,404])},
 hero:{file:'combat-hero.png',scale:420/351,frames:[[36,81,424,440,210,434],[477,6,818,438,670,434],[879,86,1439,440,1075,434],[1440,105,1749,438,1600,434],[38,513,424,873,210,867],[476,439,819,871,670,867],[880,517,1439,872,1075,867],[1439,537,1749,873,1600,867]]},
 elara:{file:'combat-elara.png',scale:420/538,frames:[[101,68,619,614,330,610],[709,24,1167,619,990,610],[33,679,745,1184,315,1178],[780,685,1219,1192,995,1185]]},
 echo:{file:'combat-echo.png',scale:420/619,frames:[[88,16,578,643,330,635],[693,13,1227,643,980,635],[12,666,686,1219,375,1212],[705,646,1240,1241,980,1233]]}
};const images={};
function paint(a){const kind=a.dataset.kind,spec=sprites[kind];if(!spec)return;let img=images[kind];if(!img){img=images[kind]=new Image();img.src=spec.file;}if(!img.complete||!img.naturalWidth){img.addEventListener('load',()=>paint(a),{once:true});return;}let index=['idle','windup','strike','hurt'].indexOf(a.dataset.pose);if(index<0)index=0;if(kind==='hero'&&document.body.classList.contains('wearing-vigilia'))index+=4;const f=spec.frames[index],canvas=a.querySelector('canvas'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,1024,768);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';const [x,y,r,b,ax,ay]=f,k=spec.scale;ctx.drawImage(img,x,y,r-x,b-y,512+(x-ax)*k,540+(y-ay)*k,(r-x)*k,(b-y)*k);}
function art(id,kind){const a=document.createElement('div');a.className='combat-art';a.dataset.kind=id==='hero'?'hero':id==='elara'?'elara':kind==='coro'?(id==='enemy'?'anchor':['left','right'].includes(id)?'pylon':'construct'):['custodian','sentinel','ash'].includes(kind)?'construct':'echo';a.dataset.pose='idle';a.setAttribute('aria-hidden','true');if(a.dataset.kind!=='construct'){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=768;a.append(canvas);paint(a);}return a;}
function pose(el,name){el.dataset.pose=name;paint(el);}
function render(s,room){const board=$('board');if(boardRef!==board||roomKey!==room||!board.querySelector('.battle-actors')){previous.clear();boardRef=board;roomKey=room;board.replaceChildren();board.style.backgroundImage=`linear-gradient(#0a17252e,#111b2366),url(scenes/${room==='plaza'?'plaza-forest':room}.png)`;for(let y=0;y<5;y++)for(let x=0;x<7;x++){const c=document.createElement('div');c.className='cell';c.dataset.x=x;c.dataset.y=y;c.setAttribute('role','gridcell');c.setAttribute('aria-label',`Fila ${y+1}, columna ${x+1}`);board.append(c);}const layer=document.createElement('div');layer.className='battle-actors';board.append(layer);}
 const active=s.order[s.index],a=s.units.find(u=>u.id===active),layer=board.querySelector('.battle-actors');
 for(const c of board.querySelectorAll('.cell')){const x=+c.dataset.x,y=+c.dataset.y,w=s.warning;const hazard=s.units.some(u=>u.hp>0&&u.warning&&u.warning.x===x&&u.warning.y===y)||w&&(w.type==='radius'?Math.abs(x-w.x)+Math.abs(y-w.y)<=2:w.type==='pulse'?y===w.y:x===w.x&&y===w.y);const reachable=a?.team==='party'&&!s.result&&s.movement>0&&Math.abs(a.x-x)+Math.abs(a.y-y)===1&&!s.units.some(u=>u.hp>0&&u.x===x&&u.y===y);c.classList.toggle('danger',!!hazard);c.classList.toggle('reachable',reachable);let mech=s.kind==='coro'?(x===3&&y===2?'Atril':x===5&&y===3?(s.serethRescued?'A salvo':'Sereth'):y===1&&(x===0||x===6)?'Interruptor':''):s.kind==='ash'&&x===3&&y===3?'Palanca':s.kind==='ash'&&y===1&&(x===0||x===6)?(s.wheels.includes(x===0?0:1)?'✓':'Soporte'):s.kind==='whisper'&&x===5&&y===1?'Foco':s.kind==='echo'&&x===5&&y===1?'Válvula':s.kind==='custodian'&&y===1&&(x===0||x===6)?(s.wheels.includes(x===0?0:1)?'✓':'Rueda'):'';c.classList.toggle('mechanism',!!mech);c.textContent=mech;}
 for(const u of s.units){let n=layer.querySelector('[data-unit="'+u.id+'"]');if(!n){n=document.createElement('div');n.className='battle-actor';n.dataset.unit=u.id;n.append(art(u.id,s.kind));const hp=document.createElement('div');hp.className='actor-health';hp.innerHTML='<span></span>';n.append(hp);layer.append(n);}const old=previous.get(u.id);n.style.left=((u.x+.5)/7*100)+'%';n.style.top=((u.y+.88)/5*100)+'%';n.style.zIndex=u.y+2;n.classList.toggle('active',u.id===active);n.classList.toggle('selected-target',s.kind==='coro'&&u.id===s.targetId);n.classList.toggle('fixed-object',['left','right','enemy'].includes(u.id)&&s.kind==='coro');n.classList.toggle('down',u.hp<=0);n.querySelector('.actor-health span').style.width=(Math.max(0,u.hp)/u.max*100)+'%';n.setAttribute('role','img');n.setAttribute('aria-label',`${u.name}: ${u.hp} de ${u.max} PG`);n.title=`${u.name} · ${u.hp}/${u.max} PG`;
 if(old&&(old.x!==u.x||old.y!==u.y)){n.classList.add('moving');clearTimeout(n.motionTimer);n.motionTimer=setTimeout(()=>n.classList.remove('moving'),440);}
 if(old&&old.hp!==u.hp){const delta=u.hp-old.hp,float=document.createElement('b');float.className='damage-float'+(delta>0?' healing':'');float.textContent=(delta>0?'+':'')+delta;n.append(float);setTimeout(()=>float.remove(),1500);if(delta<0){pose(n.firstChild,'hurt');setTimeout(()=>pose(n.firstChild,'idle'),500);}}
 previous.set(u.id,{x:u.x,y:u.y,hp:u.hp});}
 $('party-status').replaceChildren(...s.units.map(u=>{const el=document.createElement('span');el.className='party-chip'+(u.id===active?' current':'');el.textContent=`${u.name} ${u.hp}/${u.max}`;return el;}));
}
function reset(){previous.clear();roomKey='';}
async function sequence(stage,party,enemy,{defense=false,success=false,magic=false,impact}){
 const p=party.querySelector('.combat-art'),e=enemy.querySelector('.combat-art'),attacker=defense?enemy:party,target=defense?party:enemy,attArt=defense?e:p,tarArt=defense?p:e;
 const pause=ms=>new Promise(r=>setTimeout(r,ms)),duration=reduced()?1:450;
 pose(attArt,'windup');await pause(reduced()?100:280);
 const travel=(target.getBoundingClientRect().left-attacker.getBoundingClientRect().left)*.56;
 const approach=!magic?attacker.animate([{transform:'translateX(0)'},{transform:`translateX(${travel}px)`}],{duration,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'}):null;
 if(magic){const orb=document.createElement('div');orb.className='spell-orb';stage.append(orb);orb.animate([{left:'25%',opacity:0,scale:.2},{left:'35%',opacity:1,scale:1},{left:'75%',opacity:1,scale:.6}],{duration:450,fill:'forwards',easing:'ease-in'});setTimeout(()=>orb.remove(),500);}await pause(duration);pose(attArt,'strike');const result=impact();
 let damage=Object.values(result?.changes||{}).filter(x=>x<0).reduce((n,x)=>n-x,0);const splash=document.createElement('div');splash.className='impact-glow'+(magic?' arcane':'');splash.style.left=defense?'25%':'75%';stage.append(splash);setTimeout(()=>splash.remove(),650);
 if(defense&&success){target.animate([{transform:'translateX(0)'},{transform:'translateX(-24px)'},{transform:'translateX(0)'}],{duration:500,easing:'ease-out'});}else if(damage){pose(tarArt,'hurt');target.animate([{filter:'brightness(1)'},{filter:'brightness(2)',transform:'translateX(9px)'},{filter:'brightness(1)',transform:'translateX(0)'}],{duration:450});}
 const text=document.createElement('b');text.className='cinema-damage';text.textContent=damage?'−'+damage:defense&&success?'¡Defensa!':'Sin daño';target.append(text);setTimeout(()=>text.remove(),1300);
 await pause(reduced()?200:650);pose(attArt,'idle');pose(tarArt,'idle');if(approach){const back=attacker.animate([{transform:`translateX(${travel}px)`},{transform:'translateX(0)'}],{duration,easing:'ease-in-out',fill:'forwards'});approach.cancel();await pause(duration);back.cancel();}return result;
}
return {art,pose,render,reset,sequence};
})();
